/// <summary>
/// The <c>AVAsmmSalesUnitDbt_Extension</c> class is the extension of table <c>smmSalesUnit</c>
/// </summary>
[ExtensionOf(tableStr(smmSalesUnit))]
final class AVAsmmSalesUnitDbt_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>AVAfindRec</c> method.
/// </summary>
/// <param name="_smmSalesUnitRecId">
///    <c>RecId</c> as type
/// </param>
/// <param name="_forupdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>smmSalesUnit</c> as return value
/// </returns>
public static server smmSalesUnit AVAfindRec(   RecId   _smmSalesUnitRecId,
                                                boolean _forupdate          = false)
{
    smmSalesUnit locSmmSalesUnit;

    locSmmSalesUnit = null;

    if (_smmSalesUnitRecId)
    {
        locSmmSalesUnit.selectForUpdate(_forupdate);

        select firstonly locSmmSalesUnit
        where locSmmSalesUnit.RecId == _smmSalesUnitRecId;
    }

    return locSmmSalesUnit;
}

/// <summary>
///    AVA <c>AVAfind</c> method.
/// </summary>
/// <param name="_smmSalesUnitId">
///    <c>smmSalesUnitId</c> as type
/// </param>
/// <param name="_dataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
/// <param name="_forupdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>smmSalesUnit</c> as return value
/// </returns>
public static server smmSalesUnit AVAfind(  smmSalesUnitId  _smmSalesUnitId,
                                            DataAreaId      _dataAreaId,
                                            boolean         _forupdate      = false)
{
    smmSalesUnit salesUnit = null;
    container    kcs_MasterCompany;

    if (_smmSalesUnitId && _dataAreaId)
    {
        kcs_MasterCompany = conIns(kcs_MasterCompany, 1, _dataAreaId);

        salesUnit.selectForUpdate(_forupdate);

        select firstonly crosscompany : kcs_MasterCompany salesUnit
        index hint SalesUnitIdx
        where salesUnit.SalesUnitId == _smmSalesUnitId;
    }

    return salesUnit;
}

/// <summary>
///    AVA <c>AVAgetSalesUnitManager</c> method.
/// </summary>
/// <param name="_smmSalesUnitId">
///    <c>smmSalesUnitId</c> as type
/// </param>
/// <param name="_masterCompany">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>smmSalesManWorker</c> as return value
/// </returns>
public static server smmSalesManWorker AVAgetSalesUnitManager(  smmSalesUnitId  _smmSalesUnitId,
                                                                    boolean         _masterCompany = true)
{

    smmSalesUnit            salesUnit       = null;
    smmSalesUnitMembers     salesUnitMember = null;

    container    masterCompany;

    masterCompany   = connull();
    masterCompany   += _masterCompany ? KCS_KBVParameters::find().KCS_DataAreaName : curext();


    if (_smmSalesUnitId)
    {

        select firstonly crosscompany : masterCompany salesUnit
        index hint  SalesUnitIdx
        where   salesUnit.SalesUnitId == _smmSalesUnitId
            join    salesUnitMember
            where   salesUnitMember.SalesUnitId     == salesUnit.SalesUnitId
                &&  salesUnitMember.salesManager    == NoYes::Yes;
    }

    return salesUnitMember.SalesPersonWorker;
}

/// <summary>
///    AVA <c>avaGetSalesUnitCurrentWorkerIndoor</c> method.
/// </summary>
/// <param name="_hcmWorkerRecId">
///    <c>HcmWorkerRecId</c> as type
/// </param>
/// <param name="_indoorOnly">
///    <c>boolean</c> as type
/// </param>
/// <param name="_primaryOnly">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>smmSalesUnit</c> as return value
/// </returns>
public static smmSalesUnit avaGetSalesUnitCurrentWorkerIndoor(  HcmWorkerRecId  _hcmWorkerRecId = HcmWorkerLookup::currentWorker(), 
                                                                boolean         _indoorOnly     = true,
                                                                boolean         _primaryOnly    = true                              )
{
    smmSalesUnit                retVal;

    smmSalesUnitId              locsmmSalesUnitId;
    smmSalesUnit                locsmmSalesUnit;
    smmSalesUnitMembers         locsmmSalesUnitMembers;
    HcmWorkerRecId              locHcmWorkerRecId;
    NoYesId                     locsmmSalesUnitIndoorSearch;
    smmSalesUnitMemberRelation  locsmmSalesUnitMemberRelationAddSearch;

    locHcmWorkerRecId = _hcmWorkerRecId;

    if(_indoorOnly)
    {
        locsmmSalesUnitIndoorSearch = NoYes::Yes;
    }
    else
    {
        locsmmSalesUnitIndoorSearch = NoYes::No;
    }

    if(_primaryOnly)
    {
        locsmmSalesUnitMemberRelationAddSearch = smmSalesUnitMemberRelation::Primary;
    }
    else
    {
        locsmmSalesUnitMemberRelationAddSearch = smmSalesUnitMemberRelation::Secondary;
    }

    if(HcmWorker::find(locHcmWorkerRecId).RecId)
    {
        //locsmmSalesUnitId = smmSalesUnitMembers::findMemberPrimaryUnit(currentHcmWorkerRecId, false); // does not work correctly on current changes of unit members

        select firstonly SalesPersonWorker, Relation, SalesUnitId 
        from locsmmSalesUnitMembers
        index hint SalesManIdx
        order by Relation asc
        where   locsmmSalesUnitMembers.SalesPersonWorker    == _hcmWorkerRecId
            &&  (       locsmmSalesUnitMembers.Relation     == smmSalesUnitMemberRelation::Primary 
                    ||  locsmmSalesUnitMembers.Relation     == locsmmSalesUnitMemberRelationAddSearch   )
            join    locsmmSalesUnit
            where   locsmmSalesUnit.SalesUnitId                     == locsmmSalesUnitMembers.SalesUnitId
                &&  (      locsmmSalesUnit.AVAIndoorServiceControl  == NoYes::Yes 
                        || locsmmSalesUnit.AVAIndoorServiceControl  == locsmmSalesUnitIndoorSearch  )
                &&  locsmmSalesUnit.UnitType                        == smmSalesUnitType::Matrix;

        locsmmSalesUnitId = locsmmSalesUnitMembers.SalesUnitId;

        if(locsmmSalesUnitId)
        {
            retVal = smmSalesUnit::find(locsmmSalesUnitId);
        }
    }
    return retVal;
}
